#include <iostream>
#include <cstring>

int main() {
    char cs[20][8][8];
    memset(cs, 0, sizeof(cs));

    for (int i = 0; i < 8; i++) {
        std::string line;
        std::cin >> line;
        for (int x = 0; x < 8; x++) {
            cs[0][i][x] = line[x];
        }
    }

    for (int i = 0; i < 19; i++) {
        for (int y = 0; y < 8; y++) {
            for (int x = 0; x < 8; x++) {
                if (cs[i][y][x] == 'M') {
                    for (int dy = -1; dy <= 1; dy++) {
                        for (int dx = -1; dx <= 1; dx++) {
                            int xx = x + dx;
                            int yy = y + dy;
                            if (0 <= xx && xx < 8 && 0 <= yy && yy < 8 && cs[i][yy][xx] != 'S') {
                                cs[i+1][yy][xx] = 'M';
                            }
                        }
                    }
                }
            }
        }

        for (int y = 6; y >= 0; y--) {
            for (int x = 0; x < 8; x++) {
                if (cs[i][y][x] == 'S') {
                    cs[i+1][y+1][x] = 'S';
                }
            }
        }
    }

    std::string res = "LOSE";
    for (int y = 0; y < 8; y++) {
        for (int x = 0; x < 8; x++) {
            if (cs[19][y][x] == 'M') {
                res = "WIN";
            }
        }
    }
    std::cout << res << std::endl;
    return 0;
}

